ROOT.scriptdef:
IF OBJECT_ID('CDN.DF_KnS_GUID','D') IS NOT NULL ALTER TABLE CDN.KntOsoby DROP CONSTRAINT DF_KnS_GUID;
ALTER TABLE CDN.KntOsoby ALTER COLUMN KnS_GUID VARCHAR (   40)   ;
ALTER TABLE CDN.KntOsoby ADD CONSTRAINT DF_KnS_GUID  DEFAULT(CONVERT(varchar(36), NEWID())) FOR KnS_GUID WITH VALUES;

IF OBJECT_ID('CDN.DF_Naz_Nazwa1','D') IS NOT NULL ALTER TABLE CDN.Nazwy DROP CONSTRAINT DF_Naz_Nazwa1;
ALTER TABLE CDN.Nazwy ALTER COLUMN Naz_Nazwa1 VARCHAR (   30)   ;
ALTER TABLE CDN.Nazwy ADD CONSTRAINT DF_Naz_Nazwa1  DEFAULT('') FOR Naz_Nazwa1 WITH VALUES;

ALTER TABLE CDN.PrzelewyNag ADD PPN_PlikZlecenia                VARCHAR(MAX)     CONSTRAINT DF_PPN_PlikZlecenia DEFAULT('') WITH VALUES;
ALTER TABLE CDN.PrzelewyNag ADD PPN_PlikSkrot                   VARCHAR (   50)   CONSTRAINT DF_PPN_PlikSkrot DEFAULT('') WITH VALUES;
ALTER TABLE CDN.PrzelewyNag ADD PPN_MsgId                       VARCHAR (   50)   CONSTRAINT DF_PPN_MsgId DEFAULT('') WITH VALUES;

IF OBJECT_ID('CDN.DF_ZKD_Wartosc','D') IS NOT NULL ALTER TABLE CDN.ZestKSDef DROP CONSTRAINT DF_ZKD_Wartosc;
ALTER TABLE CDN.ZestKSDef ALTER COLUMN ZKD_Wartosc VARCHAR(MAX)     ;
ALTER TABLE CDN.ZestKSDef ADD CONSTRAINT DF_ZKD_Wartosc  DEFAULT('') FOR ZKD_Wartosc WITH VALUES;
